<section class="card" id="recorded-attendance"><h2>Recorded attendance</h2><p>Open a date range to view the whole register for that week. To add another day or week, use <a href="#enter-attendance">Enter attendance</a> above.</p>
<?php $groups=[];foreach($r['entries'] as $entry){$week=date('Y-m-d',strtotime('monday this week',strtotime($entry['date'])));$groups[$week][]=$entry;}krsort($groups);foreach($groups as $week=>$entries):$dates=array_column($entries,'date');?><details><summary>Attendance: <?=e(min($dates))?> – <?=e(max($dates))?></summary><?php $readOnly=true;require __DIR__.'/planner-grid.php';unset($readOnly);?></details><?php endforeach;if(!$groups):?><p>No attendance submitted yet.</p><?php endif;?></section>
<?php if(spDeleteAllowed($u,$r)):?><section class="card" id="delete-attendance"><h2><?=acAdmin($u)?'Delete complete attendance module':'Delete recorded attendance'?></h2><p><?=acAdmin($u)?'This removes the module, its regular and special timetable, drafts and recorded attendance. Staff can create this module again. An audit snapshot is retained.':'This clears recorded attendance and its draft. The module and timetable remain available.'?></p><?php spForm(acAdmin($u)?'sa_plan_module_delete':'sa_plan_clear',$r);?><label class="period-delete-confirm"><input type="checkbox" name="confirmed" value="1" required><span><?=acAdmin($u)?'I confirm deletion of this module, timetable and all its attendance.':'I confirm deletion of this module’s attendance.'?></span></label><button class="danger-button"><?=acAdmin($u)?'Delete module and all attendance':'Delete attendance'?></button></form></section><?php endif;?>
